task apps_3286__enough(cap: int, on: int, wait: int) returns (r: int)
  requires cap >= 0
  requires on >= 0
  requires wait >= 0
  ensures r == 0 or r == wait - (cap - on)
  ensures r >= 0
{
  if on + wait <= cap {
    r := 0;
  } else {
    r := wait - (cap - on);
  }
}

